/* page4-flow-data.js — 把轮播图内联为 data:URI
   file:// 协议下 WebGL 无法把本地文件当纹理上传（跨域污染），
   换成 data:URI 后不再受该限制，液态透镜效果可正常工作。
   [opt2026-10-23d] 修正两个问题：
   ① 键名与实际 src 不匹配（原写 page4-flow-N.jpg，页面里是 page4-flow-N-sm.webp），
      导致这 700KB 数据从来没被用上，等于白下载；现按真实 src 键名生成。
   ② 卡面实际显示只有 208px，原先内联的是 900px 原图，6 张解码后要占 19MB 内存，
      这是 iOS 内存吃紧、页面被系统回收（表现为“自己弹回第一页”）的主因之一。
      现统一 480px 宽（2.3x 余量），体积与解码内存同步下降。 */
window.__P4_FLOW_DATA = {
  'page4-flow-0-sm.webp': 'data:image/webp;base64,',
  'page4-flow-1-sm.webp': 'data:image/webp;base64,',
  'page4-flow-2-sm.webp': 'data:image/webp;base64,',
  'page4-flow-3-sm.webp': 'data:image/webp;base64,',
  'page4-flow-4-sm.webp': 'data:image/webp;base64,',
  'page4-flow-5-sm.webp': 'data:image/webp;base64,'
};
